starter.css:
:root {
  --surface: #ffffff;
  --text: #1f2937;
  --card: #f8fafc;
}
@media (prefers-color-scheme: dark) {
  :root {
    --surface: #0f172a;
    --text: #e5e7eb;
    --card: #1e293b;
  }
}

body {
  background: var(--surface);
  color: var(--text);
}
.hero {
  padding: 16px;
  background: var(--surface);
  color: var(--text);
}
.hero h1 { margin: 0 0 12px; font-size: 1.4rem; }
.session-card {
  margin-block: 8px;
  padding: 12px;
  border-radius: 12px;
  background: var(--card);
}

solution.css:
:root {
  color-scheme: light dark;
  --surface: light-dark(#ffffff, #0f172a);
  --text: light-dark(#1f2937, #e5e7eb);
  --card: light-dark(#f8fafc, #1e293b);
}
:root[data-theme="light"] { color-scheme: light; }
:root[data-theme="dark"] { color-scheme: dark; }

body {
  background: var(--surface);
  color: var(--text);
}
.hero {
  color-scheme: dark;
  padding: 16px;
  background: var(--surface);
  color: var(--text);
}
.hero h1 { margin: 0 0 12px; font-size: 1.4rem; }
.session-card {
  margin-block: 8px;
  padding: 12px;
  border-radius: 12px;
  background: var(--card);
}
